INSERT INTO public.reviews
(id, model_id, user_id, model_version_id, rating, title, content, pros, cons, hardware_used, use_case, verified_purchase, helpful_count)
VALUES
('81111111-1111-1111-1111-111111111111', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '88de6bb2-af6b-42dd-887a-8a260c001e33', '11111111-1111-4111-8111-111111111112', 5, 'Perfect for edge deployment', 'Deployed on Jetson Orin Nano for real-time object detection in robotics project. 54 FPS with TensorRT.', ARRAY['Fast','Easy ONNX export','Great documentation','Low memory'], ARRAY['COCO classes only','Struggles with small objects'], 'NVIDIA Jetson Orin Nano', 'Robotics object detection', true, 12),
('81111111-1111-1111-1111-111111111112', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', '4c8134e6-8523-4168-85fc-3311577be335', '11111111-1111-4111-8111-111111111112', 4, 'Solid performer', 'Good balance of speed and accuracy. Easy to integrate with ONNX Runtime.', ARRAY['Simple integration','Good accuracy','Multiple export formats'], ARRAY['Larger than MobileNet-SSD','Custom training needs Ultralytics repo'], 'Intel i7-12700K + RTX 3070', 'Warehouse monitoring', true, 8),
('82222222-2222-2222-2222-222222222222', 'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', '4c8134e6-8523-4168-85fc-3311577be335', '22222222-2222-4222-8222-222222222222', 5, 'Incredible speed for quality', '1-step generation is mind-blowing. Good enough for concept art and rapid prototyping.', ARRAY['Insanely fast','Decent quality for 1-step','Low VRAM'], ARRAY['Lower detail than 50-step','Artifacts on complex scenes','Fixed guidance scale'], 'RTX 4090 24GB', 'Concept art generation', true, 23),
('82222222-2222-2222-2222-222222222223', 'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', '88de6bb2-af6b-42dd-887a-8a260c001e33', '22222222-2222-4222-8222-222222222222', 4, 'Great for iteration', 'Perfect when you need many variations quickly. Not a replacement for full SDXL but great for ideation.', ARRAY['Fast iteration','Good for brainstorming','Low VRAM'], ARRAY['Not a replacement for full SDXL','Limited control'], 'RTX 3080 10GB', 'Rapid prototyping', true, 18),
('83333333-3333-3333-3333-333333333333', 'cccccccc-cccc-cccc-cccc-cccccccccccc', '4c8134e6-8523-4168-85fc-3311577be335', '33333333-3333-4333-8333-333333333333', 4, 'True mobile SAM', 'Runs on iPhone 15 Pro with CoreML. Impressive for mobile segmentation.', ARRAY['Actually runs on mobile','Good quality','Easy CoreML export'], ARRAY['Slower than expected on CPU','Point prompts only'], 'iPhone 15 Pro (CoreML)', 'Mobile AR app', true, 9),
('83333333-3333-3333-3333-333333333334', 'cccccccc-cccc-cccc-cccc-cccccccccccc', '88de6bb2-af6b-42dd-887a-8a260c001e33', '33333333-3333-4333-8333-333333333333', 5, 'Lightweight and effective', 'Perfect for our edge deployment. 10x smaller than SAM with minimal quality drop.', ARRAY['Tiny model size','ONNX export works','Good mIoU'], ARRAY['Single point prompt','No box prompt support'], 'Raspberry Pi 5 + Coral TPU', 'Edge segmentation', true, 6),
